// Textes de l'appli dans les 4 langues (fr rédigé en premier, en, es, it) : mêmes clés partout.
import Foundation

enum Lang {
    static let index: Int = {
        for code in Locale.preferredLanguages {
            let c = String(code.prefix(2))
            if let i = ["fr", "en", "es", "it"].firstIndex(of: c) { return i }
        }
        return 1 // langue du système hors des 4 : anglais
    }()
}

func L(_ key: String, _ args: CVarArg...) -> String {
    guard let row = table[key] else { return key }
    let s = row[Lang.index]
    return args.isEmpty ? s : String(format: s, arguments: args)
}

